// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        // No need to bound or assume; the rule must hold for all addresses
        bool result = c.approvedToLog(caller);
        assertTrue(!result, "approvedToLog should return false for any address");
    }
}

